def calculate_a_n(limit):
    a = {1: 0}
    for n in range(2, limit + 1):
        max_val = -float('inf')
        for i in range(1, n):
            term = a[i] + a[n - i] + min(i, n - i)
            if term > max_val:
                max_val = term
        a[n] = max_val
    return a

# Calculate up to n=16 to see more powers of 2
results = calculate_a_n(16)

print("n | a_n")
for n in range(1, 17):
    print(f"{n} | {results[n]}")

# Specifically check powers of 2
powers_of_2 = [n for n in range(1, 17) if (n > 0) and (n & (n - 1) == 0)]
print("\nPowers of 2 results:")
for n in powers_of_2:
    print(f"a_{n} = {results[n]}")

def calculate_a(n, memo={}):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0
    if n % 2 == 0:
        # a_{2k} = 2a_k + k
        result = 2 * calculate_a(n // 2, memo) + n // 2
    else:
        # a_{2k+1} = a_k + a_{k+1} + k, where k = (n-1)/2
        k = n // 2
        result = calculate_a(k, memo) + calculate_a(k + 1, memo) + k
    memo[n] = result
    return result

a_2025 = calculate_a(2025)
print(f"a_2025 = {a_2025}")
